 </style></head><body><div id="app"><header class="topbar"><div class="brand"><div class="mark"><span>⛏</span></div><div><div class="title">Stonewake</div><div class="subtitle">A life well levelled</div></div></div><div class="realm">REALM OF <b>GREYMERE</b></div><div class="spacer"></div><div class="coin">◈ <span id="coins">24</span> gp</div><div class="save" id="save-status">● SAVED</div></header><div class="world"><aside class="side"><div class="panel-title">Your skills</div><div id="skills"></div></aside><main class="viewport" id="viewport"><canvas id="scene"></canvas><div class="location">GREYMERE FRONTIER <b id="place">The Crossroads</b></div><div class="compass" id="compass">N</div><div class="toast" id="toast"></div><div class="prompt" id="prompt"><div class="prompt-name" id="prompt-name">Copper seam</div><div class="prompt-hint" id="prompt-hint"><span class="key">E</span> Mine copper</div><div class="prompt-progress"><i id="work-progress"></i></div></div><div class="mobile-controls"><div class="joystick" id="joystick"><div class="stick" id="stick"></div></div><button class="action-mobile" id="action-mobile">ACT</button></div></main><aside class="journal"><div class="panel-title">Field journal</div><div class="journal-level"><div class="level-top"><span id="focus-name">Explorer</span><span class="level-num" id="focus-level">1</span></div><div class="journal-sub" id="level-next">Begin at a station</div><div class="wide-track"><div class="wide-fill" id="focus-fill"></div></div></div><div class="panel-title">Pack <span id="inv-cap" style="float:right"></span></div><div class="inventory-grid" id="inventory"></div><div class="log"><div class="panel-title" style="margin-bottom:4px">Field notes</div><div id="log-lines"></div></div></aside></div></div>
 <script>(()=>{'use strict';
+const SAVE='stonewake-save-v1', skills={mining:['Mining','⛏'],smithing:['Smithing','⚒'],woodcutting:['Woodcutting','♣'],fishing:['Fishing','⌁'],cooking:['Cooking','♨'],crafting:['Crafting','◇']};
+const xpFor=l=>Math.floor(100*Math.pow(Math.max(0,l-1),1.75)),levelFor=x=>{let l=1;while(l<99&&x>=xpFor(l+1))l++;return l};
+let state={coins:24,inv:{},xp:{},equipped:'bronze',running:false,progress:0,focus:'mining'};try{const d=JSON.parse(localStorage.getItem(SAVE)||'null');if(d)state={...state,...d,running:false,progress:0,inv:d.inv||d.inventory||{}}}catch(e){}for(const k in skills)state.xp[k]=state.xp[k]||0;
+const $=s=>document.querySelector(s),canvas=$('#scene'),ctx=canvas.getContext('2d'),viewport=$('#viewport');let W=0,H=0,D=1;function resize(){const r=viewport.getBoundingClientRect();D=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=W*D;canvas.height=H*D}new ResizeObserver(resize).observe(viewport);resize();
+function save(){try{localStorage.setItem(SAVE,JSON.stringify(state));$('#save-status').textContent='● SAVED'}catch(e){$('#save-status').textContent='● UNSAVED'}}function count(id){return state.inv[id]||0}function add(id,n=1){state.inv[id]=(state.inv[id]||0)+n}function remove(id,n=1){if(count(id)<n)return false;state.inv[id]-=n;if(!state.inv[id])delete state.inv[id];return true}
+function log(t){const e=document.createElement('div');e.className='log-entry';e.innerHTML=t;$('#log-lines').prepend(e);while($('#log-lines').children.length>5)$('#log-lines').lastChild.remove()}let toastTimer;function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),1900)}
+function render(){let html='';for(const [k,[name,icon]] of Object.entries(skills)){const x=state.xp[k]||0,l=levelFor(x),pct=Math.min(100,(x-xpFor(l))/(xpFor(l+1)-xpFor(l))*100);html+=`<div class="skill"><div class="skill-icon">${icon}</div><div><div class="skill-name">${name}</div><div class="skill-xp">${x.toLocaleString()} xp</div><div class="xp-track"><div class="xp-fill" style="width:${pct}%"></div></div></div><div class="skill-level">${l}</div></div>`}$('#skills').innerHTML=html;const k=state.focus,x=state.xp[k]||0,l=levelFor(x);$('#focus-name').textContent=skills[k][0]+' level';$('#focus-level').textContent=l;$('#level-next').textContent=`${x} / ${xpFor(l+1)} xp to level ${l+1}`;$('#focus-fill').style.width=`${Math.min(100,(x-xpFor(l))/(xpFor(l+1)-xpFor(l))*100)}%`;const names={copper:['🟠','Copper ore',3],tin:['⚪','Tin ore',3],iron:['🔘','Iron ore',8],coal:['⚫','Coal',10],bronze:['🟤','Bronze bar',12],logs:['🪵','Oak logs',4],fish:['🐟','River trout',8],cooked:['🍖','Grilled trout',15],gem:['💎','Raw gemstone',35]};const entries=Object.entries(state.inv).filter(([,n])=>n>0);$('#inv-cap').textContent=`${entries.length} / 24`;$('#inventory').innerHTML=Array.from({length:24},(_,i)=>{const [id,n]=entries[i]||[];if(!id)return '<div class="slot empty"></div>';return `<div class="slot" data-id="${id}" title="${names[id]?.[1]||id}">${names[id]?.[0]||'📦'}<span class="count">${n}</span></div>`}).join('');$('#inventory').querySelectorAll('.slot:not(.empty)').forEach(el=>el.onclick=()=>{const id=el.dataset.id,n=count(id),spec=names[id]||['','Item',2],v=spec[2]*n;state.coins+=v;delete state.inv[id];toast(`Sold ${n} × ${spec[1]} for ${v} gp`);log(`Sold <b>${n} ${spec[1]}</b> for ${v} gp.`);render();save()});$('#coins').textContent=state.coins}
+function gain(k,n){const old=levelFor(state.xp[k]||0);state.xp[k]=(state.xp[k]||0)+n;if(levelFor(state.xp[k])>old){toast(`${skills[k][0]} level ${levelFor(state.xp[k])}!`);log(`<b>${skills[k][0]} reached level ${levelFor(state.xp[k])}</b>.`)}render()}
+// A small locally-rendered 3D world: perspective-projected geometry, no downloaded assets.
+const player={x:0,z:0,yaw:0,walk:0}, camera={yaw:0}, stations=[
+ {id:'mine',x:-18,z:35,name:'Copperfall Mine',type:'mine',icon:'⛏',hint:'Mine copper & tin',color:'#756b56'},
