+function project(x,y,z){const dx=x-player.x,dz=z-player.z,ang=player.yaw,rx=dx*Math.cos(ang)-dz*Math.sin(ang),rz=dx*Math.sin(ang)+dz*Math.cos(ang);const depth=rz+10;if(depth<.3)return null;const f=Math.min(W,H)*.92;return {x:W*.5+rx*f/depth,y:H*.53-(y-2.1)*f/depth+f*.23/depth,scale:f/depth,depth}}
+function poly3(points,color){const p=points.map(v=>project(v[0],v[1],v[2]));if(p.some(v=>!v))return;ctx.beginPath();ctx.moveTo(p[0].x,p[0].y);for(let i=1;i<p.length;i++)ctx.lineTo(p[i].x,p[i].y);ctx.closePath();ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='#1f302455';ctx.lineWidth=1;ctx.stroke()}
+function box(x,y,z,sx,sy,sz,color,light){const a=[x-sx/2,y,z-sz/2],b=[x+sx/2,y,z-sz/2],c=[x+sx/2,y,z+sz/2],d=[x-sx/2,y,z+sz/2],A=a.map((v,i)=>v+(i===1?sy:0)),B=b.map((v,i)=>v+(i===1?sy:0)),C=c.map((v,i)=>v+(i===1?sy:0)),D=d.map((v,i)=>v+(i===1?sy:0));poly3([a,b,B,A],light||color);poly3([b,c,C,B],color);poly3([c,d,D,C],shade(color));poly3([A,B,C,D],light||color)}
+function shade(c){return c==='#664b35'?'#493729':c==='#6e8c56'?'#547343':c==='#6c6558'?'#514c43':c==='#9b8054'?'#755f40':'#52665a'}
+function tree(x,z,s=1){const base=project(x,0,z);if(!base)return;const q=base.scale*s;box(x,0,z,.38*s,2.1*s,.38*s,'#664b35');for(let i=0;i<3;i++){const y=1.1*s+i*.85*s,r=(1.1-i*.22)*s;poly3([[x,y,z],[x-r,y-.2*s,z],[x,y+1.55*s,z],[x+r,y-.2*s,z]]);poly3([[x,y,z-r*.45],[x-r,y-.2*s,z],[x,y+1.55*s,z],[x,y-.2*s,z+r*.45]],i===0?'#426b49':'#527c50')} }
+function drawStation(s,t){const {x,z}=s;const ground=project(x,0,z);if(!ground)return;ctx.save();ctx.globalAlpha=.35;ctx.fillStyle='#19271e';ctx.beginPath();ctx.ellipse(ground.x,ground.y,ground.scale*1.9,ground.scale*.55,0,0,Math.PI*2);ctx.fill();ctx.restore();
+ if(s.type==='mine'){box(x,0,z,7,3.8,1,'#71634d');poly3([[x-4,2,z+.54],[x,5.3,z+.54],[x+4,2,z+.54]],'#493f33');poly3([[x-2.6,1.5,z+.58],[x,3.8,z+.58],[x+2.6,1.5,z+.58]],'#17201e');box(x-5,.3,z+2,1.5,1.2,1.2,'#77786b');box(x+5,.3,z+2,1.6,1.1,1.2,'#a17a4b')}
+ if(s.type==='forge'){box(x,0,z,6,3.5,4,'#866c4c');poly3([[x-3,3.4,z-2],[x,5.8,z-2],[x+3,3.4,z-2]],'#5b5140');poly3([[x-3,3.4,z+2],[x,5.8,z+2],[x+3,3.4,z+2]],'#655743');box(x-3.5,0,z+2,1,3,1,'#614a36');box(x+4,0,z+1,2,.8,1.2,'#676e68');box(x-1,0,z+3.3,1.1,1.4,.8,'#55483b');const p=project(x-1,1.5,z+3.3);if(p){ctx.fillStyle='#f6aa45';ctx.shadowColor='#f08a2b';ctx.shadowBlur=22*p.scale;ctx.beginPath();ctx.arc(p.x,p.y,Math.max(3,5*p.scale),0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}}
+ if(s.type==='woods'){for(let i=0;i<5;i++)tree(x+(i-2)*2.1,z+(i%2)*2,1.1)}
+ if(s.type==='river'){poly3([[x-10,0,z-2],[x+10,0,z-2],[x+12,0,z+5],[x-8,0,z+5]],'#528d91');for(let i=0;i<4;i++)box(x-7+i*4,.08,z+1,.12,.02,3,'#a6d1c0');box(x,0,z-4,8,.35,1,'#756047');for(let i=-1;i<=1;i++)box(x+i*3,.4,z-4,.18,.9,.18,'#594c39')}
+ const label=project(x,6,z);if(label&&label.scale>4){ctx.fillStyle='#e7e2ca';ctx.font=`${Math.max(10,Math.min(16,label.scale*1.5))}px Georgia`;ctx.textAlign='center';ctx.shadowColor='#17221f';ctx.shadowBlur=6;ctx.fillText(s.name,label.x,label.y-8);ctx.shadowBlur=0}}

